type Option interface{ apply(*options) }

type funcOption struct{ f func(*options) }

func (o funcOption) apply(opts *options) { o.f(opts) }

func WithTimeout(d time.Duration) Option {
	return funcOption{func(o *options) { o.timeout = d }}
}

type Option[T any] func(*T)

func WithTimeout[T any](d time.Duration, set func(*T, time.Duration)) Option[T] {
	return func(t *T) { set(t, d) }
}
